// Demo setup: a labeled living-room project with the owner's photo and the
// floor-plan dimensions, ready for design options. Writes to the configured
// workspace database only with --write. Previews are then generated by the
// running API process (npm run dev:api) when Muse is configured.
import { readFile } from 'node:fs/promises';
import { basename } from 'node:path';
import { workspaceMongoConfig } from '../apps/api/src/database-config.js';
import { MongoWorkspaceRepository } from '../apps/api/src/repository.js';
import { startAgentProject } from '../apps/api/src/agent-projects.js';
import { DesignImageStore } from '../apps/api/src/design-images.js';
import { CatalogStore } from '../apps/api/src/catalog.js';
import { buildDesignOptions, uploadDesignPhoto } from '../apps/api/src/design-service.js';

const photo =
  process.argv.find((arg) => arg.endsWith('.avif') || arg.endsWith('.jpg')) ??
  'docs/pics/livingroom.avif';
if (!process.argv.includes('--write')) {
  console.log(
    `Dry run. Would create "Living room refresh · demo", upload ${photo}, and build options.`,
  );
  console.log('Re-run with --write to apply to the configured workspace database.');
  process.exit(0);
}

const database = await workspaceMongoConfig();
const { repository, client } = await MongoWorkspaceRepository.connect(database.uri);
try {
  const project = await startAgentProject(repository, {
    requestId: 'living-room-demo-2026-10-29',
    name: 'Living room refresh · demo',
    brief:
      'I want to renovate my living room. (Demo project with the owner-provided photo and floor plan.)',
  });
  const images = new DesignImageStore(client.db());
  const uploaded = await uploadDesignPhoto(images, repository.ownerId, {
    bytes: new Uint8Array(await readFile(photo)),
    originalName: basename(photo),
    label: 'Living room toward the stairs and dining area (owner photo)',
    permission:
      'Owner confirmed permission to use and modify this photo, including in demo material (2026-10-29).',
  });
  // CubiCasa floor plan: living room 13'1" × 23'2" ("deemed highly reliable but
  // not guaranteed"). Relayed, unverified; the ceiling height is not on the plan.
  const built = await buildDesignOptions(repository, images, new CatalogStore(client.db()), {
    requestId: 'living-room-demo-options-1',
    projectId: project.projectId,
    request: 'I want to renovate my living room',
    sourcePhotoSha256: uploaded.image.sha256,
    reported: [
      { key: 'floorLengthFt', amount: 23.17, unit: 'ft' },
      { key: 'floorWidthFt', amount: 13.08, unit: 'ft' },
    ],
  });
  console.log(
    `Demo project ${project.projectId}; design options revision ${built.ref.revision}; source photo ${uploaded.image.sha256.slice(0, 12)}…`,
  );
} finally {
  await client.close();
}
